/**
 * 服务端网络传输层代理类
 *
 */
var NetworkBuffer = require("../util/NetworkBuffer").NetworkBuffer;
var JceCurrent = require("./JceCurrent.js").JceCurrent;
var ProtoMessage = require('../util/ProtoMessage').ProtoMessage;

///////////////////////////////////////////////协议解析器////////////////////////////////////////////////////////////

const processNet = function (stream, totalCount, networkBuffer, transceiver) {

    try {
        var count = 0;

        while (networkBuffer.getBufferLength() > 0 && count < totalCount) {

            var message = new ProtoMessage();

            if (stream.feed(networkBuffer, message)) {
        
                ++count;

                transceiver.socket.emit("message", message);
            } else {
                break;
            }

        }
    } catch (e) {
        transceiver.socket.emit("error", e);
        return false;
    }

    if (networkBuffer.getBufferLength() > 0 && count >= totalCount) {
        setTimeout(() => {
            //释放一下, 避免太多包,导致业务逻辑没空处理
            processNet(stream, totalCount, networkBuffer, transceiver)
        }, 0);
    }

    return true;
}

const feed = function (stream, networkBuffer, transceiver) {

    return processNet(stream, 50, networkBuffer, transceiver);
}

///////////////////////////////////////////////TCP网络传输类////////////////////////////////////////////////////////////
var TCPTransceiver = function () {
    this.adapter     = undefined;
    this.socket      = undefined;
    this.stream      = undefined;
    this.netthread   = undefined;
    this.uid         = 0;
    this._socket_evt = undefined;
    this._iTimeout   = 60000;

    this._networkBuffer = NetworkBuffer.New();
};
module.exports.TCPTransceiver = TCPTransceiver;

TCPTransceiver.prototype.initialize = function () {
    var self = this;

    self._socket_evt = {
        close   : function()        { self.close(); },
        error   : function()        { self.close(); },
        timeout : function ()       { self.close(); },
        data    : function(data)    {
            self._networkBuffer.addBuffer(data);

            // 如果检测到非法数据包，关闭当前连接
            // if (!self.stream.feed(data, self)) self.close();
            if (!feed(self.stream, self._networkBuffer, self)) self.close();
        },
        message : function(request) { self.adapter.dispatch(self, request); }
    };

    if(self.socket)
    {
        self.socket.on("data",    self._socket_evt.data);
        self.socket.on("error",   self._socket_evt.error);
        self.socket.on("close",   self._socket_evt.close);
        self.socket.on("timeout", self._socket_evt.timeout);
	    // self.stream.on("error",   self._socket_evt.error);
        self.socket.on("message", self._socket_evt.message);

        self.socket.setTimeout(this._iTimeout);
    }
};

TCPTransceiver.prototype.getUid = function () {
    return this.uid;
}

TCPTransceiver.prototype.close = function () { //主动或者发生错误之后，关闭本连接
    if (this.socket) {

        if (this.adapter.handleImp.doClose) {

            var current = new JceCurrent(this.adapter, this);

            try {
                this.adapter.handleImp.doClose(current);
            } catch (e) {
                
            }
        }

        this._networkBuffer.clear();

        this.netthread.remove(this.uid);

        this.socket.removeListener("error",     this._socket_evt.error);
        this.socket.removeListener("close",     this._socket_evt.close);
        this.socket.removeListener("data",      this._socket_evt.data);
        this.socket.removeListener("timeout",   this._socket_evt.timeout);
		// this.socket.removeListener("error", this._socket_evt.error);
        this.socket.removeListener("message", this._socket_evt.message);
        this.socket.destroy();

        this.socket = undefined;


    }
};

TCPTransceiver.prototype.sendBuffer = function (NodeBuffer) {

    this.socket && this.socket.write(NodeBuffer);
};

TCPTransceiver.prototype.send = function ($protoMessage) {

    this.socket && this.socket.write(this.stream.compose($protoMessage));
};

TCPTransceiver.prototype.setTimeout = function ($iTimeout) { //设置服务端连接空闲时间
    this._iTimeout = $iTimeout;
};

///////////////////////////////////////////////UDP网络传输类////////////////////////////////////////////////////////////
var UDPTransceiver = function () {
    this.adapter   = undefined;
    this.socket    = undefined;
    this.stream    = undefined;
    this.endpoint  = undefined;
    this._iTimeout = 60000;
    this._networkBuffer = new NetworkBuffer();
};
module.exports.UDPTransceiver = UDPTransceiver;

UDPTransceiver.prototype.doRequest = function ($msg) {
    var self = this;

    // self.stream.reset();
	self.stream.on("error", function (){});
    self.stream.on("message", function (request) { self.adapter.dispatch(self, request); });

    this._networkBuffer.clear();
    this._networkBuffer.addBuffer($msg);

    feed(self.stream, this._networkBuffer, self);
    // self.stream.feed($msg);
};

UDPTransceiver.prototype.sendBuffer = function (NodeBuffer) {
    this.socket && this.socket.send(NodeBuffer, 0, NodeBuffer.length, this.endpoint.iPort, this.endpoint.sHost);
};

UDPTransceiver.prototype.send = function ($protoMessage) {
    var NodeBuffer = this.stream.compose($protoMessage);

    this.socket && this.socket.send(NodeBuffer, 0, NodeBuffer.length, this.endpoint.iPort, this.endpoint.sHost);
};

UDPTransceiver.prototype.setTimeout = function ($iTimeout) { //设置服务端连接空闲时间
    this._iTimeout = $iTimeout;
};

UDPTransceiver.prototype.close = function () {

};
